SELECT mm.id AS message_id,s.id AS child_sub_id,s.sub_id AS sub_id
FROM gc_master_message AS mm
LEFT JOIN gc_user_answer AS ua ON mm.user_answer_id = ua.id
LEFT JOIN gc_event AS e ON e.id = ua.event_id
LEFT JOIN gc_video AS v ON v.id = e.video_id
LEFT JOIN courses AS s ON s.id = v.sub_id
WHERE mm.master_id = #{masterId} 
AND mm.event_type = ${@com.threeatom.guidecore.constant.MessageEventType@QUESTION_5} 
AND mm.user_id = #{userId} AND mm.target_user_id = #{targetUserId} 
AND mm.read_state = 0 AND s.id != ""

