select sch.name,sch.create_time,info.last_name,info.first_name,message.read_state,message.id as message_id ,message.user_schedule_id as scheduleId from gc_master_message message left join gc_user teacherUser on teacherUser.id = message.user_id left join gc_user_info info on teacherUser.info_id = info.id left join gc_user_schedule sch on sch.id = message.user_schedule_id where message.target_user_id = #{userId} and message.event_type = 10
and message.read_state = #{readState}
order by message.create_time desc
